import sys

def prefixSuffixString(s1, s2):
    count = 0
    for y in s2:
        if any(x.startswith(y) or x.endswith(y) for x in s1):
            count += 1
    return count

if __name__ == "__main__":
    import sys
    input = sys.stdin.read().split()
    s1 = input[:int(input[0])]
    s2 = input[int(input[0])+1:]
    print(prefixSuffixString(s1, s2))
